-- Generated by `chainindex dbt` from chains/ethereum.yaml and abis/UniswapV3Pool.json. Do not edit: change the chain file or ABI and regenerate.
-- SetFeeProtocol(uint8,uint8,uint8,uint8)
{{ config(
    materialized='view',
    schema='events_ethereum',
    alias='uniswap_v3_pool__set_fee_protocol',
    tags=['chains', 'chain_ethereum'],
) }}

select
    toUInt64(1) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    toUInt8(reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64))))) as fee_protocol0_old,
    toUInt8(reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64))))) as fee_protocol1_old,
    toUInt8(reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64))))) as fee_protocol0_new,
    toUInt8(reinterpretAsUInt256(reverse(unhex(substring(data, 195, 64))))) as fee_protocol1_new
from {{ source('chain_ethereum', 'logs') }}
where topic0 = '0x973d8d92bb299f4af6ce49b52a8adb85ae46b9f214c4c4fc06ac77401237b133'
  and address in (select address from {{ ref('ethereum__contracts') }} where contract = 'uniswap_v3_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_ethereum', 'orphaned_blocks') }}
  )
